if(preg_match('#^/admin/payout/(requested|maker-approved|bank-processing|reconciled)$#',$path,$m)&&$method==='GET'){
    SettlementService::ensureSchema($db);
    $requestedN=(int)$db->query("SELECT COUNT(*) FROM settlements WHERE status='REQUESTED'")->fetchColumn();
    $settledN=(int)$db->query("SELECT COUNT(*) FROM settlements WHERE status='SETTLED'")->fetchColumn();
    $unsettledN=(int)$db->query("SELECT COUNT(*) FROM transactions WHERE status='SUCCESS' AND COALESCE(settlement_status,'UNSETTLED')='UNSETTLED'")->fetchColumn();
    $stage='requested';if($requestedN>0||$unsettledN>0)$stage='bank_processing';elseif($settledN>0)$stage='reconciled';
    $txnSql="SELECT t.*,c.code customer_code,c.name customer_name,b.bank_name FROM transactions t JOIN customers c ON c.id=t.customer_id JOIN bank_profiles b ON b.id=t.bank_id ";
    $key=$m[1];$batches=[];
    if($key==='requested'){
        $txns=$db->query($txnSql."WHERE t.status='SUCCESS' AND COALESCE(t.settlement_status,'UNSETTLED')='UNSETTLED' ORDER BY t.id DESC LIMIT 200")->fetchAll();
        $page=['heading'=>'Requested','subtitle'=>'Successful collections waiting for a payout request.','viewStep'=>'requested','txn_title'=>'Waiting collections','txn_hint'=>'These payments are SUCCESS. They are not paid out until a settlement is requested and bank MIS is reconciled.','empty'=>'No requested payouts.','primary_href'=>'/admin/settlements','primary_label'=>'Request settlement'];
    }elseif($key==='maker-approved'){
        $batches=$db->query("SELECT * FROM settlements WHERE status='REQUESTED' ORDER BY id DESC LIMIT 200")->fetchAll();
        $txns=$db->query($txnSql."WHERE t.status='SUCCESS' AND COALESCE(t.settlement_status,'UNSETTLED')='REQUESTED' ORDER BY t.id DESC LIMIT 200")->fetchAll();
        $page=['heading'=>'Maker approved','subtitle'=>'Payout batches approved by maker and sent toward the bank.','viewStep'=>'maker','txn_title'=>'Approved items','txn_hint'=>'Maker approval is recorded when a settlement batch is requested.','empty'=>'No maker-approved batches yet.','primary_href'=>'/admin/settlements','primary_label'=>'Open settlements','batch_hint'=>'Requested settlement batches awaiting the bank.'];
    }elseif($key==='bank-processing'){
        $batches=$db->query("SELECT * FROM settlements WHERE status='REQUESTED' ORDER BY id DESC LIMIT 200")->fetchAll();
        $txns=$db->query($txnSql."WHERE t.status='SUCCESS' AND COALESCE(t.settlement_status,'UNSETTLED') IN ('UNSETTLED','REQUESTED') ORDER BY t.id DESC LIMIT 200")->fetchAll();
        $page=['heading'=>'Bank processing','subtitle'=>'Items with the bank. Success is recorded only after MIS or status evidence is reconciled.','viewStep'=>'bank_processing','txn_title'=>'In bank processing','txn_hint'=>'Do not mark these successful because a file was generated or uploaded. Reconcile bank evidence first.','empty'=>'Nothing is in bank processing.','primary_href'=>'/admin/reconciliation','primary_label'=>'Import Reverse MIS','batch_hint'=>'Batches currently with the bank.'];
    }else{
        $batches=$db->query("SELECT * FROM settlements WHERE status='SETTLED' ORDER BY id DESC LIMIT 200")->fetchAll();
        $txns=$db->query($txnSql."WHERE t.status='SUCCESS' AND COALESCE(t.settlement_status,'UNSETTLED')='SETTLED' ORDER BY t.id DESC LIMIT 200")->fetchAll();
        $page=['heading'=>'Reconciled','subtitle'=>'Payouts recorded after bank MIS or status evidence.','viewStep'=>'reconciled','txn_title'=>'Reconciled items','txn_hint'=>'These collections are marked SETTLED after bank evidence.','empty'=>'No reconciled payouts yet.','primary_href'=>'/admin/reconciliation','primary_label'=>'Open reconciliation','batch_hint'=>'Settled batches.'];
    }
    $amt=0;foreach($txns as $t)$amt+=(float)($t['confirmed_amount']??$t['requested_amount']??0);
    $stats=[['k'=>'ITEMS','n'=>(string)count($txns),'s'=>'In this stage'],['k'=>'AMOUNT','n'=>'₹'.amount_fmt($amt),'s'=>'From platform records'],['k'=>'BATCHES','n'=>(string)count($batches),'s'=>'Settlement batches']];
    view(__DIR__.'/../views/payout_flow.php',$page+compact('txns','batches','stats','stage')+['title'=>$page['heading']]);
}
